// ============================================================================
// font8x16.v - 8x16 ASCII pixel font ROM (chars 32..126)
// ----------------------------------------------------------------------------
// AUTO-GENERATED by tools/gen_font.py - do not edit by hand.
// Source font : C:\Windows\Fonts\consolab.ttf (Consolas Bold)
// Render      : 14 pt, baseline y=13 in an 8x16 px cell, threshold 128
// Data        : 2048 x 8, address = {ch[6:0], row[3:0]}, bit 7 = left pixel
//
// Gowin infers this as one BSRAM (pROM) with the contents taken from
// src/font8x16.hex.  Read latency is one clock (registered output).
// ============================================================================
`timescale 1ns / 1ps

module font8x16 (
    input  wire       clk,
    input  wire [6:0] ch,     // ASCII 0..127
    input  wire [3:0] row,    // 0..15, top to bottom
    output reg  [7:0] data    // 8 pixels of this row, registered
);
    reg [7:0] mem [0:2047];

    initial begin
        $readmemh("src/font8x16.hex", mem);
    end

    always @(posedge clk) begin
        data <= mem[{ch, row}];
    end
endmodule
